  "filename": "page_periodlog.js",
  "content": "(function(){
  const render = async (ctx) => {
    const {root, api} = ctx;
    root.innerHTML = `
      <div class="page periodlog-page">
        <h2>Period Log</h2>
        <button id="addPeriodBtn" class="btn primary">Add Period</button>
        <div id="periodList" class="list"></div>
      </div>
      <div id="periodModal" class="modal hidden">
        <div class="modal-content">
          <span class="close" id="closeModal">&times;</span>
          <h3>Add Period</h3>
          <form id="periodForm">
            <label>Start Date<input type="date" name="start_date" required></label>
            <label>End Date<input type="date" name="end_date" required></label>
            <label>Flow<input type="text" name="flow" required></label>
            <label>Symptoms<input type="text" name="symptoms"></label>
            <label>Notes<textarea name="notes"></textarea></label>
            <button type="submit" class="btn primary">Save</button>
          </form>
        </div>
      </div>
    `;

    const periodListEl = root.querySelector('#periodList');

    const showLoading = () => {
      periodListEl.innerHTML = '<p>Loading...</p>';
    };

    const renderList = (items) => {
      if (items.length === 0) {
        periodListEl.innerHTML = '<p class="empty">No period records. Click “Add Period” to begin.</p>';
        return;
      }
      const rows = items.map(item => `
        <tr data-id="${item.id}">
          <td>${item.start_date}</td>
          <td>${item.end_date}</td>
          <td>${item.flow}</td>
          <td>${item.symptoms}</td>
          <td>${item.notes}</td>
        </tr>
      `).join('');
      periodListEl.innerHTML = `
        <table class="period-table">
          <thead><tr><th>Start</th><th>End</th><th>Flow</th><th>Symptoms</th><th>Notes</th></tr></thead>
          <tbody>${rows}</tbody>
        </table>
      `;
    };

    const fetchPeriods = async () => {
      showLoading();
      try {
        const resp = await api('/api/periodlogs', {method: 'GET'});
        if (!resp.success) throw new Error('API error');
        const data = resp.data || [];
        renderList(data);
      } catch (e) {
        periodListEl.innerHTML = '<p class="error">Failed to load data.</p>';
        console.error(e);
      }
    };

    // Modal handling
    const modal = root.querySelector('#periodModal');
    const openModal = () => modal.classList.remove('hidden');
    const closeModal = () => modal.classList.add('hidden');
    root.querySelector('#addPeriodBtn').addEventListener('click', openModal);
    root.querySelector('#closeModal').addEventListener('click', closeModal);

    root.querySelector('#periodForm').addEventListener('submit', async (e) => {
      e.preventDefault();
      const form = e.target;
      const formData = new FormData(form);
      const payload = {
        start_date: formData.get('start_date'),
        end_date: formData.get('end_date'),
        flow: formData.get('flow'),
        symptoms: formData.get('symptoms') || '',
        notes: formData.get('notes') || ''
      };
      try {
        const resp = await api('/api/periodlogs', {method: 'POST', json: payload});
        if (resp.success) {
          closeModal();
          form.reset();
          fetchPeriods();
          const toast = document.createElement('div');
          toast.className = 'toast success';
          toast.textContent = 'Period added';
          document.body.appendChild(toast);
          setTimeout(() => toast.remove(), 3000);
        } else {
          throw new Error('Save failed');
        }
      } catch (err) {
        console.error(err);
        alert('Failed to save period');
      }
    });

    await fetchPeriods();
  };

  window.ForgeAI = window.ForgeAI || {};
  window.ForgeAI.registerPage = window.ForgeAI.registerPage || function(){ };
  window.ForgeAI.registerPage('periodlog', render);
})();"
}
